import os
import re

from ....exceptions import MbmsApplicationException
from ...applications.generic_app import MbmsApp
from ....utils.vm_utils import get_vm_ip_address
import builtins


class LteBroadcastApp(MbmsApp):
    """LTE Broadcast Application"""

    def __init__(self, configuration, ue):
        """

        :param configuration:
        :param ue:
        """
        super().__init__(configuration, ue)
        self._idle_mode = None
        self._prepare_config_files()

    def start(self, sessions=None):
        """
        Starts LteBroadcastApp with parameters defined in config passed during initialization
        :param sessions: names of sessions which will be listened to
        :return: None
        """
        start_cmds = [
            {'cmd': 'wait-for-device', 'is_shell_cmd': False},
            {'cmd': 'root', 'is_shell_cmd': False},
            {'cmd': 'am start -a android.intent.action.MAIN -n com.qualcomm.msdc_ui/.view.LauncherActivity', 'is_shell_cmd': True}
        ]
        if sessions is not None:
            self._idle_mode = False
            nrs = ",".join([str(length + 1) for length in range(len(sessions))])
            start_cmds.extend([
                {'cmd': 'sleep 10', 'is_shell_cmd': True},
                {'cmd': f'am start -a android.intent.action.MAIN --eia "SERVICE_LIST" {nrs} -n com.qualcomm.msdc_ui/.view.MultiServiceActivity',
                    'is_shell_cmd': True}
            ])
        else:
            self._idle_mode = True

        self._copy_sa_ota_file(sessions)
        self._execute_commands_on_ue(start_cmds)
        self.logger.info(f"MbmsApplication for ue {self.ue.name} started.")

    def _copy_sa_ota_file(self, sessions):
        fake_sa_ota_location = os.path.join(os.path.dirname(__file__))
        cmd_list = [
            {'cmd': 'cp /sdcard/sa_ota.txt /system/embms/qti/', 'is_shell_cmd': True},
            {'cmd': 'cp /sdcard/sa_ota.txt /system/embms/qcom/', 'is_shell_cmd': True},
            {'cmd': 'chmod 777 /system/embms/qti/*', 'is_shell_cmd': True},
            {'cmd': 'chmod 777 /system/embms/qcom/*', 'is_shell_cmd': True},
        ]
        if self._idle_mode:
            fake_sa_ota_file_path = os.path.join(fake_sa_ota_location, 'fake_sa_ota.txt')
            cmd_list.insert(0, {'cmd': f'push {self._copy_file_to_ue_pc_and_return_path(fake_sa_ota_file_path)} /sdcard/sa_ota.txt',
                                'is_shell_cmd': False})
        else:
            cleaned_sa_ota_file_path = os.path.join(os.path.dirname(self._configuration["sa_ota_file_path"]), "cleaned_sa_ota.txt")
            self._clean_not_used_sessions_from_sa_ota_file(self._configuration["sa_ota_file_path"], cleaned_sa_ota_file_path, *sessions)
            cmd_list.insert(0, {'cmd': f'push {self._copy_file_to_ue_pc_and_return_path(cleaned_sa_ota_file_path)} /sdcard/sa_ota.txt',
                                'is_shell_cmd': False}, )
        self._execute_commands_on_ue(cmd_list)

    def _clean_not_used_sessions_from_sa_ota_file(self, sa_ota_old_file_path, sa_ota_new_file_path, *used_sessions):
        with builtins.open(sa_ota_old_file_path, 'r') as aggregated_file:
            sa_ota_content = aggregated_file.read()
        all_sessions = set(re.findall("<!-- (.+?)_head -->", sa_ota_content))
        for not_used_session in all_sessions - set(used_sessions):
            head_tag = f"<!-- {not_used_session}_head -->"
            head_section = self._extract_section_between_tags(sa_ota_content, head_tag, head_tag)
            sa_ota_content = sa_ota_content.replace(head_section, "")
            body_tag = f"<!-- {not_used_session}_body -->"
            body_section = self._extract_section_between_tags(sa_ota_content, body_tag, body_tag)
            sa_ota_content = sa_ota_content.replace(body_section, "")

        with builtins.open(sa_ota_new_file_path, 'w', newline='\r\n') as aggregated_file:
            aggregated_file.write(sa_ota_content)

    def _extract_section_between_tags(self, source_text, start_tag, end_tag):
        pattern = f"({start_tag}.+?{end_tag})"
        extracted_section = re.search(pattern, source_text, re.DOTALL).group(1) + "\n"
        return extracted_section

    def stop(self):
        """
        Stops already running LteBroadcastApp.

        Fires exception if application was not started yet.
        No action if application is already stopped.
        :return: None
        """
        stop_cmds = [
            {'cmd': 'wait-for-device', 'is_shell_cmd': False},
            {'cmd': 'root', 'is_shell_cmd': False},
            {'cmd': 'am force-stop com.qualcomm.msdc_ui', 'is_shell_cmd': True},
            {'cmd': 'am force-stop com.qualcomm.ltebc', 'is_shell_cmd': True}
        ]
        self._execute_commands_on_ue(stop_cmds)
        if os.path.isfile(os.path.join(os.path.dirname(self._configuration["sa_ota_file_path"]), "cleaned_sa_ota.txt")):
            os.remove(os.path.join(os.path.dirname(self._configuration["sa_ota_file_path"]), "cleaned_sa_ota.txt"))
        self.logger.info(f"MbmsApplication for ue {self.ue.name} stopped.")

    def _prepare_config_files(self):
        config_files_location = os.path.join(os.path.dirname(__file__), "config_files")
        config_files = os.listdir(config_files_location)
        common_cmd_list = [
            {'cmd': 'wait-for-device', 'is_shell_cmd': False},
            {'cmd': 'root', 'is_shell_cmd': False},
            {'cmd': 'wait-for-device', 'is_shell_cmd': False},
            {'cmd': 'remount /system', 'is_shell_cmd': False},
            {'cmd': 'wait-for-device', 'is_shell_cmd': False},
            {'cmd': 'setenforce 0', 'is_shell_cmd': True},
            {'cmd': 'am force-stop  com.qualcomm.msdc_ui', 'is_shell_cmd': True},
            {'cmd': 'am force-stop  com.qualcomm.ltebc', 'is_shell_cmd': True},
            {'cmd': 'rm -rf /data/data/com.qualcomm.ltebc/cache', 'is_shell_cmd': True},
            {'cmd': 'rm -rf /data/data/com.qualcomm.ltebc/code_cache', 'is_shell_cmd': True},
            {'cmd': 'rm -rf /data/data/com.qualcomm.ltebc/files', 'is_shell_cmd': True},
            {'cmd': 'rm -rf /system/embms', 'is_shell_cmd': True},
            {'cmd': 'mkdir /system/embms/', 'is_shell_cmd': True},
            {'cmd': 'mkdir -p /sdcard/msdcui', 'is_shell_cmd': True},
            {'cmd': 'cp /sdcard/msdcui.properties /sdcard/msdcui/', 'is_shell_cmd': True},
            {'cmd': 'setprop persist.radio.sib16_support 1', 'is_shell_cmd': True},
            {'cmd': 'chmod 777 /sdcard/msdcui', 'is_shell_cmd': True},
            {'cmd': 'chmod 777 /sdcard/msdcui/msdcui.properties', 'is_shell_cmd': True},
            {'cmd': 'logcat -c', 'is_shell_cmd': False},
        ]

        for config_file in config_files:
            sa_ota_file_path = os.path.join(config_files_location, config_file)

            common_cmd_list.insert(8, {'cmd': f'push {self._copy_file_to_ue_pc_and_return_path(sa_ota_file_path)} /sdcard/', 'is_shell_cmd': False})

        self._execute_commands_on_ue(common_cmd_list)

        for config_dir in ['qcom', 'qti']:
            cmd_list = [
                {'cmd': f'mkdir /system/embms/{config_dir}', 'is_shell_cmd': True},
                {'cmd': f'cp /sdcard/config_params.xml /system/embms/{config_dir}/', 'is_shell_cmd': True},
                {'cmd': f'cp /sdcard/debug_params.xml /system/embms/{config_dir}/', 'is_shell_cmd': True},
                {'cmd': f'cp /sdcard/provisioning_params.xml /system/embms/{config_dir}/', 'is_shell_cmd': True},
                {'cmd': f'cp /sdcard/sa_bootstrap.txt /system/embms/{config_dir}/', 'is_shell_cmd': True},
            ]
            self._execute_commands_on_ue(cmd_list)

    def _copy_file_to_ue_pc_and_return_path(self, filepath):
        filename = os.path.basename(filepath)
        directory = os.path.dirname(filepath)
        vm_ip = get_vm_ip_address(ifname='eth0')
        sa_oute_ue_pc_filepath = self.ue.copy_file_from_remote_to_ue_pc(host=vm_ip, directory=directory, filename=filename)
        return sa_oute_ue_pc_filepath

    def _execute_commands_on_ue(self, command_list):
        error_strings = ['error', 'fatal', 'no such file']
        for item in command_list:
            output, error = self.ue.execute_adb_command(item['cmd'], item['is_shell_cmd'])
            for error_string in error_strings:
                if (not item['is_shell_cmd']) and (error_string.lower() in output.lower()):
                    error += output
            if error:
                raise MbmsApplicationException("ADB Command {} FAILED. output:{} error:{}".format(item['cmd'], output, error))
